#include "document.h"
#include <iostream>
#include <stdexcept>
using namespace moon;
static void check(bool value,const char* text){if(!value)throw std::runtime_error(text);}
static std::string slot(Document& d,int row,int column){const auto& s=d.timeline().state();return d.timeline().findCel(s.layers.at(row).id,s.frames.at(column).id)->id;}
static Pixel pixel(Document& d,int row,int column){return d.timeline().resolveSurface(slot(d,row,column)).surface->pixels[0];}
static void fixture(Document& d){for(int i=0;i<3;++i)d.addFrame();for(int i=0;i<2;++i)d.addLayer();for(int r=0;r<3;++r)for(int c=0;c<4;++c){d.selectLayer(d.timeline().state().layers[r].id);d.selectFrame(d.timeline().state().frames[c].id);d.beginStroke({0,0},0xff000000|(r*16+c+1));d.commitStroke();}}
int main(){try{
 Document d(2,1);fixture(d);const auto layers=d.timeline().state().layers;const auto frames=d.timeline().state().frames;const auto history=d.historySize();
 d.selectTimelineLayer(layers[0].id);d.selectTimelineLayer(layers[2].id,2);check(d.timelineSelection().layers.size()==3,"layer shift range");d.selectTimelineLayer(layers[1].id,1);check(d.timelineSelection().layers.size()==2,"layer ctrl toggle");check(d.historySize()==history,"selection creates document history");
 d.selectTimelineCel(slot(d,0,0));d.selectTimelineCel(slot(d,1,1),2);check(d.timelineSelection().cels.size()==4,"cel additive rectangle");d.selectTimelineCel(slot(d,1,1),1);check(d.timelineSelection().cels.size()==3,"cel toggle off");check(d.timelineSelection().layers.empty(),"plain cel retains row selection");
 d.selectTimelineCel(slot(d,0,0));d.selectTimelineCel(slot(d,0,1),1);auto original=d.timelineSelection().cels;auto h=d.historySize();
 d.moveTimelineCels(slot(d,0,0),slot(d,0,1));check(d.historySize()==h+1 && pixel(d,0,0)==0 && pixel(d,0,1)==0xff000001 && pixel(d,0,2)==0xff000002,"overlap block move");check(d.timelineSelection().cels==std::vector<std::string>{slot(d,0,1),slot(d,0,2)},"destination selection");d.undo();check(pixel(d,0,0)==0xff000001 && pixel(d,0,1)==0xff000002 && d.timelineSelection().cels==original && d.frame().id==frames[1].id,"cel undo pixels selection active context");d.redo();check(pixel(d,0,0)==0,"cel redo");d.undo();
 d.moveTimelineCels(slot(d,0,0),slot(d,1,2),true);check(pixel(d,0,0)==0xff000001 && pixel(d,1,2)==0xff000001 && pixel(d,1,3)==0xff000002,"alt copy block");d.undo();check(d.timelineSelection().cels==original,"copy undo selection");h=d.historySize();d.moveTimelineCels(slot(d,0,0),slot(d,2,3));check(d.historySize()==h && pixel(d,0,0)==0xff000001,"out of bounds transaction must reject whole block");
 d.selectTimelineLayer(layers[0].id);d.selectTimelineLayer(layers[2].id,1);h=d.historySize();d.moveTimelineLayers(layers[1].id,true);check(d.timeline().state().layers[0].id==layers[1].id && d.timeline().state().layers[1].id==layers[0].id && d.timeline().state().layers[2].id==layers[2].id,"nonadjacent layers stable order move");d.undo();check(d.timeline().state().layers[0].id==layers[0].id && d.timelineSelection().layers.size()==2,"layer move undo");d.moveTimelineLayers(layers[1].id,false,true);check(d.timeline().state().layers.size()==5 && d.timelineSelection().layers.size()==2,"multi layer alt copy");d.undo();check(d.timeline().state().layers.size()==3,"layer copy undo one step");d.redo();check(d.timeline().state().layers.size()==5,"layer copy redo");
 Document f(2,1);fixture(f);auto ids=f.timeline().state().frames;f.selectFrameHeader(ids[0].id);f.selectFrameHeader(ids[1].id,1);auto selected=f.selectedFrames();const auto anchor=f.frameSelectionAnchor(),active=f.frame().id;h=f.historySize();f.copyTimelineFrames(ids[0].id,false);check(f.timeline().state().frames.size()==6 && f.historySize()==h+1 && f.timeline().state().frames[2].id==ids[0].id,"frame copies before first atomic");f.undo();check(f.timeline().state().frames.size()==4 && f.selectedFrames()==selected && f.frameSelectionAnchor()==anchor && f.frame().id==active,"copy frame selection/context undo");f.redo();check(f.timeline().state().frames.size()==6,"frame copy redo");
 Document linked(2,1);linked.beginStroke({0,0},0xff123456);linked.commitStroke();linked.setLayerAutoLinkAnimationCels(linked.layer().id,true);linked.addFrame();linked.addFrame();linked.setLayerAutoLinkAnimationCels(linked.layer().id,false);linked.addFrame();linked.selectTimelineCel(slot(linked,0,0));linked.moveTimelineCels(slot(linked,0,0),slot(linked,0,3));check(pixel(linked,0,0)==0 && pixel(linked,0,1)==0xff123456 && pixel(linked,0,2)==0xff123456 && pixel(linked,0,3)==0xff123456,"moving canonical preserves linked siblings");linked.undo();check(linked.timeline().findCelById(slot(linked,0,1))->linkedCelId.has_value(),"linked undo restores source link");
 std::cout<<"Timeline selections, block moves/copies and history passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
